mapper.select:
SELECT r.id, r.user_id, r.category_id, r.type, r.amount, r.date, r.created_at,
       c.name AS category_name
FROM finance_record r
LEFT JOIN finance_category c ON r.category_id = c.id
WHERE r.user_id = #{userId}

    AND r.category_id = #{categoryId}


    AND r.type = #{type}

ORDER BY r.date DESC, r.created_at DESC

mapper.update:
UPDATE finance_record
category_id = #{categoryId}, type = #{type}, amount = #{amount}, date = #{date},
WHERE id = #{id}

mapper.select:
SELECT COALESCE(SUM(amount), 0)
FROM finance_record
WHERE user_id = #{userId}
  AND type = #{type}
  AND DATE_FORMAT(date, '%Y-%m') = #{yearMonth}
